POST_MESSAGE({
  "text": "In the first block, with a base price of 20 credits per MWh, it's beneficial to charge my battery as there are no stored MWh and no other actions from other owners. I'll charge up to 10 MWh since it's the maximum capacity. There's no special note to add.",
  "channel": "public"
})

POST_MESSAGE({
  "text": "Planning to charge 10 MWh during the first block to maximize storage for the coming blocks with higher prices.",
  "channel": "private"
})

```json
[{
    "type": "post_message",
    "function": {
        "name": "post_message",
        "arguments": {
            "text": "Round 1, block 1 of 4 (night): base price 20 credits per MWh. My battery is currently uncharged. I plan to charge my battery this block, adding up to 10 MWh. I will hold my other actions for now."
        }
    }
}]
```

function calls: 
[
    {
        "type": "function",
        "function": {
            "name": "charge",
            "description": "Buy and store energy this block at the realized price.",
            "parameters": {
                "amount": 10
            }
        }
    }
]

